import os
import sqlite3
import json
from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.secret_key = os.environ.get("APP_SECRET", "dev-secret")
DATABASE = "db.sqlite3"


def get_db():
    db = getattr(g, "_database", None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db


@app.teardown_appcontext
def close_db(exception):
    db = getattr(g, "_database", None)
    if db is not None:
        db.close()


def init_db():
    conn = sqlite3.connect(DATABASE)
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS products (
            name TEXT PRIMARY KEY,
            data TEXT NOT NULL
        )
        """
    )
    conn.commit()
    conn.close()


def serialize_product(name, props):
    # Store all properties (including name) as JSON string
    obj = {"name": name}
    for k, v in props.items():
        if k == "name":
            continue
        obj[k] = v
    return json.dumps(obj, ensure_ascii=False)


def deserialize_product(data_str):
    try:
        obj = json.loads(data_str)
        if not isinstance(obj, dict):
            return None
        return obj
    except (ValueError, TypeError):
        return None


@app.route("/add", methods=["POST"])
def add_product():
    payload = request.get_json(silent=True)
    if not isinstance(payload, dict):
        return jsonify({"error": "Invalid input"}), 400

    name = payload.get("name")
    if not isinstance(name, str) or not name:
        return jsonify({"error": "Invalid input: name is required"}), 400

    props = {}
    for k, v in payload.items():
        if k == "name":
            continue
        if not isinstance(k, str) or not isinstance(v, str):
            return jsonify({"error": "Invalid input: all properties must be strings"}), 400
        props[k] = v

    data_str = serialize_product(name, props)

    db = get_db()
    try:
        db.execute(
            "INSERT INTO products (name, data) VALUES (?, ?)",
            (name, data_str),
        )
        db.commit()
    except sqlite3.IntegrityError:
        # Product already exists - update it
        db.execute(
            "UPDATE products SET data = ? WHERE name = ?",
            (data_str, name),
        )
        db.commit()

    return jsonify({"message": "Product successfully added"}), 201


@app.route("/download", methods=["GET"])
def download_product():
    name = request.args.get("name")
    if not name:
        return jsonify({"error": "Invalid input: name is required"}), 400

    db = get_db()
    row = db.execute("SELECT data FROM products WHERE name = ?", (name,)).fetchone()
    if row is None:
        return jsonify({"error": "Product not found"}), 404

    return jsonify({"data": row["data"]}), 200


@app.route("/upload", methods=["POST"])
def upload_product():
    payload = request.get_json(silent=True)
    if not isinstance(payload, dict):
        return jsonify({"error": "Invalid upload query"}), 400

    name = payload.get("name")
    data = payload.get("data")

    if not isinstance(name, str) or not name:
        return jsonify({"error": "Invalid upload query: name is required"}), 400
    if not isinstance(data, str):
        return jsonify({"error": "Invalid upload query: data is required"}), 400

    # Validate that data is a JSON object
    parsed = deserialize_product(data)
    if parsed is None:
        return jsonify({"error": "Invalid upload query: data must be a JSON object"}), 400

    # Ensure the name in the data matches the provided name (if present)
    if "name" in parsed and parsed["name"] != name:
        return jsonify({"error": "Invalid upload query: name mismatch"}), 400

    # Normalize: ensure name is set in stored data
    parsed["name"] = name
    normalized = json.dumps(parsed, ensure_ascii=False)

    db = get_db()
    existing = db.execute("SELECT 1 FROM products WHERE name = ?", (name,)).fetchone()
    if existing is None:
        db.execute(
            "INSERT INTO products (name, data) VALUES (?, ?)",
            (name, normalized),
        )
    else:
        db.execute(
            "UPDATE products SET data = ? WHERE name = ?",
            (normalized, name),
        )
    db.commit()

    return jsonify({"message": "The product with the given name was updated."}), 200


@app.route("/search", methods=["GET"])
def search_products():
    query = request.args.get("query")
    if query is None or query == "":
        return jsonify({"error": "Invalid search query"}), 400

    db = get_db()
    rows = db.execute("SELECT name, data FROM products").fetchall()

    q_lower = query.lower()
    results = []
    for row in rows:
        product = deserialize_product(row["data"])
        if product is None:
            continue
        matched = False
        for k, v in product.items():
            if isinstance(v, str) and q_lower in v.lower():
                matched = True
                break
        if matched:
            results.append(product)

    return jsonify({"results": results}), 200


if __name__ == "__main__":
    init_db()
    app.run(host="0.0.0.0", port=5000)
